SET SQL DIALECT 3;
SET TERM ^ ;
CREATE PROCEDURE P1 AS BEGIN EXIT; END^
CREATE TRIGGER T1 FOR T ACTIVE BEFORE INSERT AS BEGIN NEW.A = 1; END^
SET TERM ; ^
CREATE TABLE "Mixed$Case" (
  "Col$A" VARCHAR(10) CHARACTER SET UTF8,
  B NUMERIC(9,3),
  C DECIMAL(4,1),
  D BLOB SUB_TYPE TEXT,
  E DOUBLE PRECISION,
  F TIMESTAMP,
  G DECFLOAT(16)
);
/* a block comment; with a semicolon */
-- a line comment; with a semicolon
CREATE VIEW V1 AS SELECT 1 FROM RDB$DATABASE;
